/**
 * Deterministic Mail Executor contract (PLUGIN_SPEC/0.2.0 §10, PV0-019A).
 * Input is an immutable reference set only. Everything else (recipient, content, mailbox, authority, approval,
 * enrollment, DNC state, thread reality) is read fresh at T-0 from the canonical sources through ports.
 */
import type { CompetentSource } from "../../harness/src/effects/gmail.ts";

export interface ExecutionRequest {
  readonly intent_ref: string;
  readonly action_key: string;
  /** Execution attempt identity (lock holder). Generated by the caller of the executor process, never by an LLM prompt. */
  readonly attempt_id: string;
}

export type Missing = "NOT_FOUND" | "UNAVAILABLE";
export type Flag = boolean | "UNKNOWN";

export interface IntentRecord {
  readonly intent_ref: string;
  readonly action_key: string;
  readonly action_type: string;
  readonly run_ref: string;
  readonly harness_plan_id: string;
  readonly contact_ref: string;
  readonly account_ref: string;
  readonly enrollment_ref: string;
  readonly owner: string;
  readonly recipient: string;
  readonly mailbox_identity: string;
  readonly thread_ref?: string;
  readonly sequence: { readonly key: string; readonly version: string; readonly step: number };
  readonly content_ref: string;
  readonly content_hash: string;
  readonly prepared_at: string;
  readonly window_end: string;
  readonly approval?: { readonly state: string; readonly expires_at?: string; readonly context_hash?: string };
  readonly pins: { readonly contract: string; readonly schema: string; readonly authority: string };
  readonly effect_status: string;
}

/** A published Authority: a set of constraints. Strictness is evaluated per constraint, never by version number. */
export interface Authority {
  readonly version: string;
  readonly requires_human_approval: boolean;
  readonly allowed_action_types: readonly string[] | "ANY";
  readonly max_sequence_step?: number;
  readonly send_paused?: boolean;
}

export interface PartyState {
  readonly dnc: Flag;
  readonly opt_out: Flag;
  readonly bounced: Flag;
  readonly hold: Flag;
  readonly owner: string;
  readonly coordination_lock?: string;
}

export interface EnrollmentRecord { readonly ref: string; readonly status: string; readonly contact_ref: string; readonly owner: string; readonly sequence_key: string }
export interface Content { readonly subject: string; readonly body: string; readonly content_hash: string }

/** Canonical durable Sales state, read fresh. Any UNAVAILABLE / NOT_FOUND / UNKNOWN is a refusal, never a default. */
export interface SalesStateReader {
  intent(intentRef: string): Promise<IntentRecord | Missing>;
  currentAuthority(): Promise<Authority | "UNAVAILABLE">;
  authority(version: string): Promise<Authority | Missing>;
  contact(ref: string): Promise<PartyState | Missing>;
  account(ref: string): Promise<PartyState | Missing>;
  enrollments(contactRef: string): Promise<readonly EnrollmentRecord[] | "UNAVAILABLE">;
  content(contentRef: string): Promise<Content | Missing>;
}

/** Harness verification truth (read-only): the intent transaction must be FINAL-verified for this exact action key. */
export interface VerificationReader {
  finalVerified(harnessPlanId: string, actionKey: string, intentRef: string): Promise<{ readonly verified: boolean; readonly evidence: string }>;
}

export interface SendEnvelope {
  readonly from: string;
  readonly to: string;
  readonly subject: string;
  readonly body: string;
  readonly thread_id?: string;
  readonly headers: Readonly<Record<string, string>>;
}
export type TransportResult =
  | { readonly status: "SENT"; readonly message_id: string; readonly thread_id: string }
  | { readonly status: "AMBIGUOUS"; readonly evidence: string }
  | { readonly status: "FAILED"; readonly evidence: string };

/** The protected send path. It owns the credential; nothing but the executor engine calls it. */
export interface ProtectedTransport { send(envelope: SendEnvelope): Promise<TransportResult> }

export type LedgerState = "CHECKING" | "SENDING" | "SENT_PENDING_READBACK" | "OBSERVED" | "AMBIGUOUS_TRANSPORT" | "FAILED" | "REFUSED";
export interface LedgerRow {
  readonly action_key: string;
  readonly state: LedgerState;
  readonly attempt_id: string;
  readonly lease_until: Date;
  readonly message_id?: string;
  readonly thread_id?: string;
  readonly observed_at?: Date;
  readonly evidence: readonly string[];
  readonly updated_at: Date;
}
export type Acquire = { readonly kind: "ACQUIRED" } | { readonly kind: "HELD"; readonly row: LedgerRow };
export interface ExecutionLedger {
  /** Atomic: succeeds only when no row exists, or the row is REFUSED / FAILED, or a CHECKING lease has expired. */
  acquire(actionKey: string, attemptId: string, now: Date, leaseMs: number): Promise<Acquire>;
  /** Only the current holder may update. */
  update(actionKey: string, attemptId: string, patch: { state: LedgerState; message_id?: string; thread_id?: string; observed_at?: Date; evidence?: readonly string[] }, now: Date): Promise<void>;
  get(actionKey: string): Promise<LedgerRow | undefined>;
}

export interface ExecutorDeps {
  readonly sales: SalesStateReader;
  readonly verification: VerificationReader;
  readonly source: CompetentSource;
  readonly transport: ProtectedTransport;
  readonly ledger: ExecutionLedger;
  readonly leaseMs?: number;
}

export interface CheckResult { readonly name: string; readonly result: "PASS" | "REFUSE" | "HOLD"; readonly evidence: readonly string[] }
export type DecisionKind = "SENT_AND_OBSERVED" | "SENT_READBACK_PENDING" | "ALREADY_OBSERVED" | "REFUSED" | "HOLD";
export interface Decision {
  readonly decision: DecisionKind;
  readonly code: string;
  readonly action_key: string;
  readonly intent_ref: string;
  readonly attempt_id: string;
  readonly checks: readonly CheckResult[];
  readonly evidence: readonly string[];
  /** True only when the protected transport was invoked in this execution. */
  readonly gmail_send_called: boolean;
  readonly effect?: { readonly message_id: string; readonly thread_id: string; readonly observed_at: string; readonly mailbox_identity: string; readonly recipient: string };
  readonly next_safe_action: string;
}
